/**
 * Get the URL for the previous request.
 *
 * @param  mixed  $fallback
 * @return string
 */
public function previous($fallback = false)
{
    $request = $this->request;
    $headers = $request->headers;
    $server = $request->server;

    $referrer = $request->header('referer');
    $hostHeader = $headers->get('HOST');
    $requestUri = $server->get('REQUEST_URI');

    $scheme = $request->getScheme();
    $host = $request->getHost();
    $port = $request->getPort();
    $baseUrl = $request->getBaseUrl();

    if ($host === '' || $host === null) {
        $host = $hostHeader ?: '';

        if (is_string($host) && str_contains($host, ':') && ! str_starts_with($host, '[')) {
            $host = explode(':', $host, 2)[0];
        }
    }

    if ($baseUrl === '' && is_string($requestUri) && str_contains($requestUri, 'index.php')) {
        $uriPath = explode('?', $requestUri, 2)[0];
        $position = strpos($uriPath, 'index.php');

        if ($position !== false) {
            $baseUrl = rtrim(substr($uriPath, 0, $position), '/');
        }
    }

    if (($scheme === 'http' && 80 == $port) || ($scheme === 'https' && 443 == $port)) {
        $httpHost = $host;
    } else {
        $httpHost = $host.':'.$port;
    }

    $requestRoot = rtrim($scheme.'://'.$httpHost.$baseUrl, '/');
    $generatorRoot = $this->formatRoot($this->formatScheme());
    $root = $requestRoot === $generatorRoot ? $requestRoot : $generatorRoot;

    if ($referrer) {
        if ($this->isValidUrl($referrer)) {
            $url = $referrer;
        } else {
            [$path, $query] = $this->extractQueryString($referrer);
            $url = $this->format($root, '/'.trim($path, '/')).$query;
        }
    } else {
        $session = $this->sessionResolver ? call_user_func($this->sessionResolver) : null;
        $url = $session ? $session->previousUrl() : null;
    }

    if ($url) {
        return $url;
    } elseif ($fallback) {
        if ($this->isValidUrl($fallback)) {
            return $fallback;
        }

        [$path, $query] = $this->extractQueryString($fallback);

        return $this->format($root, '/'.trim($path, '/')).$query;
    }

    return $this->format($root, '/');
}

/**
 * Get the previous path info for the request.
 *
 * @param  mixed  $fallback
 * @return string
 */
public function previousPath($fallback = false)
{
    $previousPath = str_replace($this->to('/'), '', rtrim(preg_replace('/\?.*/', '', $this->previous($fallback)), '/'));

    return $previousPath === '' ? '/' : $previousPath;
}

/**
 * Generate an absolute URL to the given path.
 *
 * @param  string  $path
 * @param  mixed  $extra
 * @param  bool|null  $secure
 * @return string
 */
public function to($path, $extra = [], $secure = null)
{
    // First we will check if the URL is already a valid URL. If it is we will not
    // try to generate a new one but will simply return the URL as is, which is
    // convenient since developers do not always have to check if it's valid.
    if ($this->isValidUrl($path)) {
        return $path;
    }

    $tail = implode('/', array_map(
        'rawurlencode', (array) $this->formatParameters($extra))
    );

    // Once we have the scheme we will compile the "tail" by collapsing the values
    // into a single string delimited by slashes. This just makes it convenient
    // for passing the array of parameters to this URL as a list of segments.
    $root = $this->formatRoot($this->formatScheme($secure));

    [$path, $query] = $this->extractQueryString($path);

    return $this->format(
        $root, '/'.trim($path.'/'.$tail, '/')
    ).$query;
}

